-- 0731_academy_gate_on_refresh.sql
-- Release 33, part G (docs/changes/2026-11-07-r33-hire-academy-connector.md, item 2): the academy gate on, and the
-- academy brought up to the features of releases 28 to 32.
-- 1. The gate (0207) is on by default and on now: a section must be passed before the next (as before), and a staff
--    member who has not passed their paths opens only the academy, the guide and their profile.
--    Who it holds is per enrollment (academy_enrollments, 0730): a hire from one-step Hire is held from the start; every
--    staff member already working is enrolled now with a week before the hold starts (lock_from), so nobody is shut out
--    of the portal mid-shift by the new sections below. Existing progress (lessons watched, quizzes passed, sections an
--    Admin opened early) is kept as it is: nothing is deleted or reset.
--    A staff member on no enrollment (made by hand in Admin > Staff) is enrolled the first time the gate is checked.
-- 2. Four new sections, appended at the end of each role's path (so passed sections stay passed):
--    new-bookings-r28-r32 (customer service, both Sales, fleet, field, Admin), new-documents-r28-r32 (customer service,
--    both Sales, field, Admin), new-money-r28-r32 (finance, Admin), new-cars-r28-r32 (fleet, Admin): 9 lessons and 20
--    quiz questions written from docs/changes of releases 28 to 32 (r28 platform and operations, the licence reader,
--    extension offers and the late fee, r32 booking flows).

alter table program_settings alter column academy_gate set default true;
update program_settings set academy_gate = true where not academy_gate;
comment on column program_settings.academy_gate is 'Academy gate (0207; on by default since 0731): a section must be passed before the next, and a staff member who has not passed every path of their functions opens only the academy, the guide and their profile from their enrollment''s lock_from (academy_enrollments). Off: the academy records progress only.';

-- everyone already working: enrolled now, held from a week from now
select sp.user_id, c, true, now() + interval '7 days', 'existing'
  from staff_profiles sp cross join lateral unnest(app.academy_paths_of(sp.user_id)) c
 where sp.is_active and c <> 'admin'
on conflict (user_id, path_code) do nothing;

-- the hold: the gate on, a staff member (not an Admin) with their paths not all passed, from their enrollment's lock_from
-- (a staff member without an enrollment is held from now, as a hire is)
create or replace function app.academy_locked(p_user uuid) returns boolean
language sql stable security definer set search_path = public, app as $$
  select coalesce((app.settings()).academy_gate, false) and not app.user_is_admin(p_user)
     and exists (select 1 from user_roles r where r.user_id = p_user and r.role in ('va', 'field'))
     and not app.academy_done(p_user)
     and coalesce((select min(e.lock_from) from academy_enrollments e where e.user_id = p_user and e.gate), now()) <= now()
$$;

-- the home read says when the hold starts
create or replace function app.academy_home(p_user uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  select jsonb_build_object('paths', coalesce((select jsonb_agg(app.academy_path_progress(p_user, c) order by ap.sort) from unnest(app.academy_paths_of(p_user)) c join academy_paths ap on ap.code = c), '[]'::jsonb),
    'gate', coalesce((app.settings()).academy_gate, false), 'locked', app.academy_locked(p_user), 'pass_bps', (app.settings()).academy_pass_bps,
    'lock_from', (select min(e.lock_from) from academy_enrollments e where e.user_id = p_user and e.gate))
$$;

