insert into academy_enrollments (user_id, path_code, gate, lock_from, source)
insert into academy_sections (slug, title, blurb) values ('new-bookings-r28-r32', 'New since release 28: bookings, handovers and returns', 'Booked when the renter accepts, one screen for check-out and check-in, the renter''s own check-in, Returned in one tap, reopening an offer and the extension options.') on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 1, 'Booked when the renter accepts', '[{"caption":"Accepted means booked","say":"A booking the renter accepted is booked: it takes the car on every calendar, even before the payment is in. Payment is a badge, never the reason.","visual":{"kind":"title","heading":"Booked, payment due","text":"The car is taken the moment the renter accepts"}},{"caption":"The first to accept gets the car","say":"When two offers are open on the same car and dates, the first renter to accept gets it. The other offers go back to Requests at once with a Re-offer To do.","visual":{"kind":"rule","heading":"Two offers, one car","text":"The first acceptance wins; the other goes back to Requests to re-offer.","tone":"ok"}},{"caption":"Unpaid close to pickup","say":"A booked rental still unpaid within 48 hours of the pickup raises a To do. Send the pay link or call the renter.","visual":{"kind":"list","heading":"Booked, payment due","items":["A badge on the booking and the Now board","A To do 48 hours before pickup","Send the pay link or call"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 2, 'One screen, the renter''s own check-in, Returned', '[{"caption":"One screen","say":"Check-out and check-in are one screen on the booking: the time, km, fuel, many photos at once and a note. Only the time is needed; with km, fuel and a photo there is nothing left to add later.","visual":{"kind":"steps","heading":"Check-out or check-in","items":["The time","Km and fuel","Photos, many at once","A note if needed"]}},{"caption":"The renter checks in and returns themselves","say":"From 24 hours before pickup the renter can check in on their booking, and press I''ve returned the car at the end. Their photos join the same report.","visual":{"kind":"list","heading":"The renter''s own steps","items":["Check in from 24 hours before","Their own photos join the report","I''ve returned the car at the end"]}},{"caption":"Returned in one tap","say":"An overdue car, or one due back today, has Returned on To do, Bookings Now, the booking page and Cars now. Give the time it came back (never in the future), km and fuel if known. Late alerts stop; Fleet gets a To do to add the photos and readings.","visual":{"kind":"rule","heading":"Returned","text":"The time it came back; km and fuel if known. Late alerts stop.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 3, 'Offers past pickup and extensions', '[{"caption":"Reopen an offer","say":"An offer that expired can be reopened by Admin, customer service and Sales with Reopen offer. An offer sent after its pickup time no longer expires at once.","visual":{"kind":"title","heading":"Reopen offer","text":"On the expired offer"}},{"caption":"Extensions instead of late returns","say":"The renter extends from their booking: six options with a discount, approved at once when the car is free, even after the return time while the car is still out.","visual":{"kind":"list","heading":"Extension options","items":["1 hour, 3 hours","1 day, 3 days","1 week, 1 month"]}},{"caption":"The late fee","say":"A late return costs 17.5% of the booking''s daily rate for each started hour after the 30 minute grace, at least $25 an hour. A booking made before the change keeps its flat $25.","visual":{"kind":"money","heading":"Late fee at $80 a day","rows":[["17.5% of $80","$14.00"],["The minimum applies","$25.00 an hour"]],"total":["Each started hour","$25.00"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 1, 'A renter accepted the offer but has not paid yet. Is the car taken?', '["No, only once paid","Yes: accepted means booked, payment is a badge","Only if an Admin confirms","Only for 24 hours"]'::jsonb, 1, 'An accepted booking is booked: it takes the car on every calendar; payment due is a badge.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 2, 'Two renters have open offers for the same car and dates. What happens when one accepts?', '["Both are booked","The first to accept gets the car; the other goes back to Requests with a Re-offer To do","The second one is charged a fee","Nothing until an Admin decides"]'::jsonb, 1, 'The first acceptance wins; the other offer returns to Requests to re-offer.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 3, 'What do you need to record a car as Returned?', '["The renter''s signature","Photos of every angle","The time it came back (never in the future); km and fuel if known","An Admin''s approval"]'::jsonb, 2, 'Returned needs only the return time; km and fuel when known. Fleet adds photos and readings later.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 4, 'What is the late fee on a new booking at $80 a day?', '["$25 flat a day","17.5% of the daily rate an hour, so the $25 minimum an hour","$14 an hour","Nothing in the first 3 hours"]'::jsonb, 1, '17.5% of $80 is $14, under the $25 minimum, so $25 for each started hour after the 30 minute grace.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-bookings-r28-r32'), 5, 'A renter is running late with the car still out. What is best to suggest?', '["Return it late and pay the fee","Extend in their booking: a discount, approved at once when the car is free","Call back tomorrow","Cancel the booking"]'::jsonb, 1, 'Extensions cost less than the late fee and can be done even after the return time while the car is out.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
