insert into academy_path_sections (path_code, section_id, sort) select 'sales_remote', (select id from academy_sections where slug = 'new-bookings-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'sales_remote' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-bookings-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'new-bookings-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'new-bookings-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb) values ('new-documents-r28-r32', 'New since release 28: licences, photos and agreements', 'The licence reader and the main driver''s Ontario licence, the camera or the photo library, amendments without re-signing, and the renter''s quick links.') on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-documents-r28-r32'), 1, 'The licence reader', '[{"caption":"Every licence is read","say":"Every licence photo is read when it is stored: the barcode on the back first, else the picture. The driver''s empty licence fields are filled and the renter confirms them.","visual":{"kind":"title","heading":"Read on upload","text":"Barcode first, then the picture"}},{"caption":"The checks","say":"The review shows a Pass or Flag line for each check: sharp and whole photos, valid to the return, the class, the minimum age, name and date of birth match, the Ontario number, front and back the same licence, and the main driver''s Ontario licence.","visual":{"kind":"list","heading":"Checks","items":["Sharp and whole","Valid to the return","Class and minimum age","Name and date of birth match","The main driver holds an Ontario licence"]}},{"caption":"Staff still approve","say":"A blurry or cut-off photo is refused at once with one plain sentence to take it again. Staff still approve the licence unless an Admin turned on automatic approval when every check passes.","visual":{"kind":"rule","heading":"Approval","text":"Flags wait for staff; nothing is approved on a flag.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-documents-r28-r32'), 2, 'Photos, amendments and quick links', '[{"caption":"Camera or photo library","say":"Licence and document uploads offer Take a photo or Choose from my photos, so an iPhone can pick from the library. Selfies stay camera only.","visual":{"kind":"list","heading":"Uploads","items":["Take a photo","Choose from my photos","Selfies: camera only"]}},{"caption":"Amendments without re-signing","say":"A booking change after signing keeps the signed agreement in force: the agreement gets a new version marked Amended with the date and the renter receives it. Only an additional driver who never signed signs.","visual":{"kind":"rule","heading":"Amended","text":"No new signature for a booking change; a new driver signs.","tone":"ok"}},{"caption":"The renter''s quick links","say":"The renter''s home shows Upload your licence, Upload proof of insurance and Check if your credit card covers rentals while the next booking needs them. The request and offer emails link straight to the licence upload when it is missing.","visual":{"kind":"steps","heading":"Quick links","items":["Upload your licence","Upload proof of insurance","Check the credit card coverage"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-documents-r28-r32'), 1, 'Which driver must hold an Ontario licence?', '["Every driver","The main driver","Only drivers under 25","Nobody"]'::jsonb, 1, 'The main driver''s Ontario licence is one of the licence checks.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-documents-r28-r32'), 2, 'The licence reader flags the class. What happens?', '["The licence is approved anyway","It waits for staff to review; nothing is approved on a flag","The booking is cancelled","The renter is charged"]'::jsonb, 1, 'Staff still approve; a flag always waits for review.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-documents-r28-r32'), 3, 'A booking''s dates change after the renter signed. Do they sign again?', '["Yes, always","No: a new version marked Amended keeps the signed agreement in force","Only by paper","Only if the price goes down"]'::jsonb, 1, 'Booking updates keep the signed agreement in force; only a driver who never signed signs.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-documents-r28-r32'), 4, 'A renter on an iPhone cannot find their saved licence photo. What do you tell them?', '["Use a computer","Press Choose from my photos on the upload","Email it to us","Take a selfie instead"]'::jsonb, 1, 'Uploads offer Take a photo or Choose from my photos.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-documents-r28-r32'), 5, 'A licence photo is blurry. What happens?', '["It is approved anyway","The person is told at once, in one sentence, to take it again","The booking is cancelled","Staff type the licence in"]'::jsonb, 1, 'A photo that cannot be used is refused at once with one plain sentence to take it again.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
