insert into academy_sections (slug, title, blurb) values ('new-money-r28-r32', 'New since release 28: money', 'One card charge for the rental and fees, deposits that stay holds, the cleaning fee, partner invoices, repair costs and kickbacks, and owner referral shares.') on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-money-r28-r32'), 1, 'Charges and deposits', '[{"caption":"One card charge","say":"The rental and fees charge the card on file once for what is open, split in the database across the rental and the fees, the rental first. One Stripe receipt; the Money tab shows the split.","visual":{"kind":"money","heading":"One charge","rows":[["Rental","$420.00"],["Fees","$35.00"]],"total":["One card charge","$455.00"]}},{"caption":"Deposits stay holds","say":"A deposit is a hold of any length, renewed before it lapses: Re-authorize the hold places a new hold on the saved card, then releases the old one. A hold nearing expiry with the car out raises a To do for Finance instead of a capture.","visual":{"kind":"rule","heading":"Never captured to keep it","text":"Re-authorize the hold before it lapses.","tone":"ok"}},{"caption":"The cleaning fee","say":"An excessively dirty car is charged $300 at check-in and taken from the deposit, the same as smoking.","visual":{"kind":"money","heading":"Cleaning, excessively dirty","rows":[["Fee","$300.00"]]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-money-r28-r32'), 2, 'Partners, repairs and referrals', '[{"caption":"Invoices to partners","say":"Invoices to partners are PI-numbered, with lines as a share of the partner''s total or fixed, HST per line, one reminder before and after the due date, and a ledger per partner and claim.","visual":{"kind":"steps","heading":"A partner invoice","items":["Lines and HST","Send with the PDF link","Record money received with a photo of the cheque"]}},{"caption":"Repair costs and kickbacks","say":"Each car''s page lists its repair costs and the kickbacks partners paid on it. Add a repair cost with the date, the shop, what was done, the amount and the tax.","visual":{"kind":"list","heading":"Kickbacks and repairs","items":["Per car","Per claim","In the company totals"]}},{"caption":"Owner referral shares","say":"An owner who referred another owner gets a referral share line on their statement for each referred car, paid from CarmaCars'' share and added to the payout.","visual":{"kind":"title","heading":"Referral share","text":"From CarmaCars'' share, on the referrer''s statement"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-money-r28-r32'), 1, 'How many card charges does "The rental and fees" make?', '["One per part","One, split across the rental and the fees","Two, one each","None: it sends a link"]'::jsonb, 1, 'One charge for what is open, split in the database, the rental first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-money-r28-r32'), 2, 'A deposit hold is about to expire while the car is still out. What do you do?', '["Capture it","Re-authorize the hold","Release it","Nothing"]'::jsonb, 1, 'Deposits stay holds: re-authorize before they lapse; never capture to keep them.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-money-r28-r32'), 3, 'What is the fee for an excessively dirty car?', '["$100","$150","$300","$500"]'::jsonb, 2, 'The cleaning fee for an excessively dirty car is $300, taken from the deposit.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-money-r28-r32'), 4, 'Where is an owner''s referral share paid from?', '["The referred owner''s share","CarmaCars'' share","The renter","The deposit"]'::jsonb, 1, 'The referral share comes out of CarmaCars'' share and is added to the referrer''s payout.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-money-r28-r32'), 5, 'What does a partner invoice number start with?', '["CC","PI","INV","OW"]'::jsonb, 1, 'Invoices to partners are PI-numbered.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'finance', (select id from academy_sections where slug = 'new-money-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'finance' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'new-money-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb) values ('new-cars-r28-r32', 'New since release 28: cars and listings', 'The VIN by photo or camera, listing photos in any order, covering the plate, owner handoffs and calendar sync.') on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-cars-r28-r32'), 1, 'Starting and photographing a listing', '[{"caption":"The VIN by photo","say":"Start a listing takes the VIN from the car: Scan the barcode in the door frame or under the windshield, or a Photo of the VIN.","visual":{"kind":"list","heading":"The VIN","items":["Scan the barcode","Photo of the VIN","Type it if both fail"]}},{"caption":"Photos in any order","say":"Add photos takes up to 30 at once, in any order: each is sorted to its shot. 10 photos with one outside photo complete the listing; outside photos are framed on the studio background.","visual":{"kind":"title","heading":"Up to 30 at once","text":"Each photo finds its shot"}},{"caption":"Cover the plate","say":"A visible plate is covered before the photo is published; check the cover on the review and fix it by hand if it missed.","visual":{"kind":"rule","heading":"Plates","text":"Never publish a readable plate.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-cars-r28-r32'), 2, 'Handoffs and calendars', '[{"caption":"Pickup from and return to the owner","say":"A car picked up from or returned to its owner gets a handoff record: the time, km, fuel, photos and notes. The owner sees it read only.","visual":{"kind":"steps","heading":"Owner handoff","items":["Time, km, fuel","Photos","Notes"]}},{"caption":"Calendar sync","say":"A car on Turo or Getaround must never be booked twice. Turo''s trip emails block the car by themselves; block each CarmaCars booking on the car''s Turo calendar and press Done on Turo.","visual":{"kind":"rule","heading":"Never twice","text":"Block CarmaCars bookings on Turo, then Done on Turo.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-cars-r28-r32'), 1, 'How many photos can Add photos take at once?', '["5","10","Up to 30, in any order","One at a time"]'::jsonb, 2, 'Up to 30 at once; each is sorted to its shot.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-cars-r28-r32'), 2, 'What completes a listing''s photos?', '["3 photos","10 photos with one outside photo","Only interior photos","30 photos"]'::jsonb, 1, '10 photos with one outside photo complete the listing.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-cars-r28-r32'), 3, 'Turo cannot read our calendar. What do you do for a CarmaCars booking of a car on Turo?', '["Nothing","Block it on the car''s Turo calendar, then press Done on Turo","Email Turo","Unlist the car"]'::jsonb, 1, 'Block each CarmaCars booking on Turo, then press Done on Turo.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-cars-r28-r32'), 4, 'How does Start a listing take the VIN?', '["Only typed by hand","Scan the barcode in the door frame or under the windshield, or a photo of the VIN","From the owner''s email","From the plate"]'::jsonb, 1, 'Scan the barcode or take a photo of the VIN.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-cars-r28-r32'), 5, 'A photo shows a readable plate. What do you do before it is published?', '["Nothing","Check the plate cover and fix it by hand if it missed","Delete the listing","Blur the whole photo"]'::jsonb, 1, 'Never publish a readable plate: check the cover and fix it by hand if needed.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-cars-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'new-cars-r28-r32'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
